CREATE TABLE conversation_message (id BIGINT NOT NULL AUTO_INCREMENT,session_id BIGINT NOT NULL,message_key VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,role VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,content MEDIUMTEXT NOT NULL,model_name VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NULL,metadata JSON NOT NULL DEFAULT (JSON_OBJECT()),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_conversation_message_key UNIQUE(session_id,message_key),KEY idx_conversation_message_session(session_id,created_at),KEY idx_conversation_message_cursor(session_id,id),CONSTRAINT ck_conversation_message_key CHECK(message_key IS NULL OR REGEXP_LIKE(message_key,'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$','c')),CONSTRAINT ck_conversation_message_role CHECK(role IN ('user','assistant')),CONSTRAINT fk_conversation_message_session FOREIGN KEY(session_id) REFERENCES conversation_session(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
